composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      DB_HOSTNAME: {{env.DB_HOSTNAME}}
      DB_USERNAME: {{env.DB_USERNAME}}
      DB_PASSWORD: {{env.DB_PASSWORD}}
      DB_DATABASE_NAME: {{env.DB_DATABASE_NAME}}
      REDIS_HOSTNAME: {{env.REDIS_HOSTNAME}}
      TZ: {{env.TZ}}
    volumes:
      - {{appDataPath}}/upload:/usr/src/app/upload
      - /etc/localtime:/etc/localtime:ro
    depends_on:
      - {{serviceName}}-redis
      - {{serviceName}}-postgres
  {{serviceName}}-machine-learning:
    image: ghcr.io/immich-app/immich-machine-learning:release
    container_name: {{serviceName}}-machine-learning
    restart: unless-stopped
    volumes:
      - {{appDataPath}}/model-cache:/cache
  {{serviceName}}-redis:
    image: redis:7-alpine
    container_name: {{serviceName}}-redis
    restart: unless-stopped
  {{serviceName}}-postgres:
    image: ghcr.io/immich-app/postgres:14-vectorchord0.4.3-pgvectors0.2.0
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_PASSWORD: {{env.DB_PASSWORD}}
      POSTGRES_USER: {{env.DB_USERNAME}}
      POSTGRES_DB: {{env.DB_DATABASE_NAME}}
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
